import { userFederatedIdentityProjectionToValue } from './user-federated-identity.model';
import { ComponentFixture, TestBed } from '@angular/core/testing';
import {
  InteractionMocks,
  RepositoryMock,
  allow,
  configureFeatureTesting,
  createWithoutTemplate,
  internals,
  mockRepository,
  mockTick,
  moduleCompiles,
} from 'app/shared/testing/feature-testing';

describe('userFederatedIdentityProjectionToValue', () => {
  const value = {
    uid: 'value-uid',
    user: { $ref: 'ref-user' },
    loginProvider: { $ref: 'ref-loginProvider' },
    subject: 'value-subject',
    createdAt: 'value-createdAt',
    version: 'value-version',
  } as any;

  it('returns null without projection', () => {
    expect(userFederatedIdentityProjectionToValue(null)).toBeNull();
    expect(userFederatedIdentityProjectionToValue(undefined)).toBeNull();
  });

  it('keeps a plain value', () => {
    expect(userFederatedIdentityProjectionToValue(value)).toEqual(value);
  });

  it('reduces the projected references to their key', () => {
    const projection = {
      uid: 'value-uid',
      user: () => ({ uid: 'ref-user' }),
      loginProvider: () => ({ uid: 'ref-loginProvider' }),
      subject: 'value-subject',
      createdAt: 'value-createdAt',
      version: 'value-version',
    } as any;
    expect(userFederatedIdentityProjectionToValue(projection)).toEqual(value);
  });
});
